const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  // Use a viewport that matches a poster aspect ratio but is large enough
  await page.setViewportSize({ width: 1200, height: 1800 });

  page.on('console', msg => console.log('CONSOLE:', msg.type(), msg.text()));
  page.on('pageerror', err => console.log('PAGE ERROR:', err.message));

  await page.goto('file:///app/output/hunger-crisis-poster.html');
  await page.waitForTimeout(5000);

  // Check SVG dimensions
  const svgInfo = await page.evaluate(() => {
    const svg = document.querySelector('#container svg');
    if (!svg) return null;
    return {
      viewBox: svg.getAttribute('viewBox'),
      width: svg.getAttribute('width'),
      height: svg.getAttribute('height'),
      style: svg.getAttribute('style'),
      boundingWidth: svg.getBoundingClientRect().width,
      boundingHeight: svg.getBoundingClientRect().height,
    };
  });
  console.log('SVG info:', svgInfo);

  const container = await page.$('#container');
  if (container) {
    await container.screenshot({ path: '/app/output/final_poster.png', type: 'png' });
    console.log('Screenshot saved');
  }
  await browser.close();
})();

