const { chromium } = require('playwright');
const fs = require('fs');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.setViewportSize({ width: 1200, height: 800 });

  page.on('console', msg => console.log('CONSOLE:', msg.type(), msg.text()));
  page.on('pageerror', err => console.log('PAGE ERROR:', err.message));

  await page.goto('file:///app/output/hunger-crisis-poster.html');
  await page.waitForTimeout(3000);

  const svgDataUrl = await page.evaluate(async () => {
    return await window.infographic.toDataURL({ type: 'svg' });
  });

  console.log('Data URL prefix:', svgDataUrl.substring(0, 100));

  let svgString;
  if (svgDataUrl.startsWith('data:image/svg+xml;base64,')) {
    const svgBase64 = svgDataUrl.replace('data:image/svg+xml;base64,', '');
    svgString = Buffer.from(svgBase64, 'base64').toString('utf-8');
  } else if (svgDataUrl.startsWith('data:image/svg+xml,')) {
    svgString = decodeURIComponent(svgDataUrl.replace('data:image/svg+xml,', ''));
  } else {
    svgString = svgDataUrl;
  }

  fs.writeFileSync('/app/output/poster.svg', svgString);
  console.log('SVG saved to /app/output/poster.svg');
  console.log('SVG length:', svgString.length);

  await browser.close();
})();

const { chromium } = require('playwright');
const fs = require('fs');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.setViewportSize({ width: 1200, height: 800 });

  page.on('console', msg => console.log('CONSOLE:', msg.type(), msg.text()));
  page.on('pageerror', err => console.log('PAGE ERROR:', err.message));

  await page.goto('file:///app/output/hunger-crisis-poster.html');
  await page.waitForTimeout(3000);

  const svgDataUrl = await page.evaluate(async () => {
    // The infographic instance is stored in a local const, but we can access the container's SVG
    const svg = document.querySelector('#container svg');
    if (!svg) return null;
    const serializer = new XMLSerializer();
    const svgStr = serializer.serializeToString(svg);
    return 'data:image/svg+xml;base64,' + btoa(unescape(encodeURIComponent(svgStr)));
  });

  if (!svgDataUrl) {
    console.log('No SVG found');
    await browser.close();
    return;
  }

  console.log('Data URL prefix:', svgDataUrl.substring(0, 100));

  let svgString;
  if (svgDataUrl.startsWith('data:image/svg+xml;base64,')) {
    const svgBase64 = svgDataUrl.replace('data:image/svg+xml;base64,', '');
    svgString = Buffer.from(svgBase64, 'base64').toString('utf-8');
  } else if (svgDataUrl.startsWith('data:image/svg+xml,')) {
    svgString = decodeURIComponent(svgDataUrl.replace('data:image/svg+xml,', ''));
  } else {
    svgString = svgDataUrl;
  }

  fs.writeFileSync('/app/output/poster.svg', svgString);
  console.log('SVG saved to /app/output/poster.svg');
  console.log('SVG length:', svgString.length);

  await browser.close();
})();
